import cadquery as cq
def bx(x0, x1, y0, y1, z0, z1): return cq.Workplane('XY').box(x1 - x0, y1 - y0, z1 - z0).translate(((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2))
blk = cq.Workplane('XZ').polyline([(-59.1, -69.5), (-47.4, -81.1), (70.9, -81.1), (100, -52), (100, 40.4), (83.6, 56.8), (5.3, 56.8), (-11.2, 40.4), (-47.4, 40.4), (-59.1, 28.7)]).close().extrude(62.8, both=True)
blk = blk.intersect(cq.Workplane('XY').polyline([(100, 51.1), (88.3, 62.8), (-47.4, 62.8), (-59.1, 51.1), (-59.1, -51.1), (-47.4, -62.8), (88.3, -62.8), (100, -51.1)]).close().extrude(100, both=True))
blk = blk.intersect(cq.Workplane('YZ').polyline([(51.1, 56.8), (-51.1, 56.8), (-62.8, 45.1), (-62.8, -65.5), (-51.1, -81.1), (51.1, -81.1), (62.8, -65.5), (62.8, 45.1)]).close().extrude(120, both=True))
knob = cq.Workplane('XY').polyline([(-59, 0), (-59, 41.5), (-65, 41.5), (-76, 40.2), (-86, 35.8), (-94.4, 29.4), (-100, 22.5), (-100, 0)]).close().revolve(360, (0, 0, 0), (1, 0, 0)).translate((0, 0, -20.2))
boss = cq.Workplane('XY').add(cq.Solid.makeLoft([cq.Workplane('XY', origin=(0, 0, z)).center(cx, 0).rect(w, h).wires().val() for z, cx, w, h in ((50, 13.1, 104.8, 55.2), (69.9, 15.5, 92.4, 46.2), (81.1, 15.5, 62.6, 17.4))], True))
b = blk.union(knob).union(boss)
b = b.cut(bx(-101, -40, -17.5, 17.5, -37.7, -2.7).edges('|X').chamfer(5.8))
tun = cq.Workplane('YZ', origin=(-6.3, 0, 0)).center(0, -22).circle(42.9).extrude(110).union(cq.Workplane('XY').sphere(42.9).rotate((0, 0, 0), (0, 1, 0), 90).translate((-6.3, 0, -22)))
tun = tun.union(bx(-6.3, 110, -24.6, 24.6, -90, -22)).union(cq.Workplane("XY", origin=(0, 0, -90)).center(29.3, 0).circle(38.5).extrude(49.1)).union(bx(29.3, 110, -38.5, 38.5, -90, -40.9)).union(bx(-6.3, 110, -25.2, 25.2, -22, 21.4))
r = b.cut(tun)
cone = cq.Workplane('XZ').polyline([(0, 0), (16.9, 0), (10, 6.8), (0, 6.8)]).close().revolve(360, (0, 0, 0), (0, 1, 0))
for s in (1, -1):
    r = r.cut(cone.rotate((0, 0, 0), (1, 0, 0), 90 if s > 0 else -90).translate((54.1, s * 62.81, -38.4)))
